import { NextResponse } from 'next/server';
import { connectToDatabase, isDbConnected } from '@/lib/mongodb';

export async function GET() {
  await connectToDatabase();
  const connected = isDbConnected();
  const uri = process.env.MONGODB_URI || 'mongodb://localhost:27017/service_center_db';
  const maskedUri = uri.replace(/\/\/([^:]+):([^@]+)@/, '//***:***@');

  return NextResponse.json({
    connected,
    status: connected ? 'connected' : 'standby',
    message: connected ? 'Connected to MongoDB' : 'Standby Cache Mode (MongoDB offline or not yet connected)',
    uri: maskedUri
  });
}
